BASE=Path(__file__).resolve().parents[1];OUT=BASE/'.cache/batch200/drafts/rewrite_vid'
BASEH=[['希腊 boutyron → 拉丁 butyrum','黄油；希腊词的更早来源有争议']]
W=[E('butter','英 /ˈbʌtə/；美 /ˈbʌtər/','黄油；给……抹黄油','把从奶油中搅打分离出的乳脂做成可涂抹的黄油，就是 butter。放到 toast 前面作动词时，butter the toast 就是给吐司抹黄油。','英语继承古英语 butere，属于西日耳曼语早期从拉丁 butyrum 借入的一族；拉丁词接希腊 boutyron。希腊词常解释成 bous“牛”加 tyros“奶酪”，但这种拆法也可能是对更早外来词的再解释，不能当成已无争议的事实。',BASEH+[['西日耳曼语早期借入 → 古英语 butere；buterian','黄油；涂黄油的动词'],['中古英语 buter／butter → 现代 butter','保留食物名与涂抹动作；后来出现讨好等比喻用法']],'名词通常不可数：some butter、一小块 a pat of butter。动词很直观，就是把它抹上去。butter someone up 则把“涂得顺滑、说得甜”变成“奉承、讨好”的画面；这是记忆联想，不是对所有历史细节的断言。','spread butter on bread；melt the butter；butter a slice of toast；butter someone up。','butter 通常是乳脂制成的黄油，cream 是奶油，margarine 是人造黄油；peanut butter 等名称则按类似的可涂抹质地延伸，不表示一定含乳制黄油。',('The recipe calls for a small knob of butter.','食谱要求放一小块黄油。'),('She buttered the toast while the eggs were cooking.','煎蛋的时候，她给吐司抹了黄油。'),('He tried to butter me up before asking for a favour.','他想先讨好我，再请我帮忙。'),sources=['https://www.etymonline.com/word/butter','https://www.oxfordlearnersdictionaries.com/definition/english/butter_1']),E('butyric','/bjuːˈtɪrɪk/','丁酸的；与丁酸有关的','butyric acid 是丁酸。这个名称从“黄油”来：它与黄油等脂肪材料的化学研究有关，游离丁酸的气味也常让人联想到酸败黄油。','从法语 butyrique 借入，远接拉丁 butyrum“黄油”；现代可看出 butyr- 与形容词后缀 -ic。它不是把现代英语 butter 按读音改几下就造出的普通形容词。',BASEH+[['法语 butyrique','用“黄油”这一命名材料形成化学形容词'],['英语 butyric，常见于 butyric acid','丁酸的；丁酸这一化学名称的组成部分']],'这里已经进入化学命名：丁酸是一种四个碳的羧酸。黄油中有关成分通常以酯的形式存在，不能把“名称来自黄油”理解为黄油就是一杯游离丁酸。日常想说食物黄油味浓，通常用 buttery，而不是 butyric。','butyric acid；butyric fermentation；butyric acid production。','buttery 常说像黄油的味道或质地；butyric 通常指特定化学关联。词根同源，不代表两个形容词在菜谱里能互换。',('The chemistry text gives butanoic acid as another name for butyric acid.','化学教材把 butanoic acid 列为 butyric acid（丁酸）的另一名称。'),('The report measured butyric acid in the sample.','报告测定了样品中的丁酸。'),sources=['https://www.merriam-webster.com/dictionary/butyric','https://www.collinsdictionary.com/dictionary/english/butyric','https://www.ncbi.nlm.nih.gov/mesh/68020148']),E('butyrate','英 /ˈbjuːtɪreɪt/；美 /ˈbjuːtəreɪt/','丁酸盐；丁酸酯；丁酸根','把丁酸想作这组名称的中心：它形成相应的盐或酯时，名称里就会见到 butyrate。sodium butyrate 是丁酸钠，ethyl butyrate 是丁酸乙酯，二者不是同一种物质。','现代化学命名用 butyr-，对应 butyric acid“丁酸”的词干，加 -ate 命名相关盐、酯或阴离子。更早经丁酸这一命名系统接拉丁 butyrum“黄油”；不把它拆成英语 butter 加动词后缀。',BASEH+[['近代 butyric acid 命名中的 butyr-；化学 -ate','丁酸词干；相应盐、酯、阴离子的命名形式'],['英语 butyrate','丁酸盐、丁酸酯，或依上下文指丁酸根']],'完整名称决定具体说的是哪一种。例如钠盐与乙酯含有共同的丁酸相关部分，却具有不同组成。生物学文章也常直接用 butyrate 来谈丁酸相关的代谢物；不要只凭这个词就推断产品成分、剂量或作用。','sodium butyrate；ethyl butyrate；butyrate levels。一般读音重在词首，与 butyric 的重音位置不同。','butyric 常作形容词，butyrate 常作物质名称。酸、对应的盐和酯在名称上相关，但并不可以当作同一种化学形态。',('The bottle was labelled sodium butyrate, not butyric acid.','瓶子上标的是丁酸钠，不是丁酸。'),('The lesson compares a butyrate salt with a butyrate ester.','这节课比较了一种丁酸盐和一种丁酸酯。'),sources=['https://www.merriam-webster.com/dictionary/butyrate','https://www.collinsdictionary.com/dictionary/english/butyrate','https://www.cancer.gov/publications/dictionaries/cancer-drug/def/sodium-butyrate'])]
names=[x['word'] for x in W];cat=next(x for x in json.loads((BASE/'.cache/catalog.json').read_text()) if x['id']=='C0149');EX={w:'较专门的化学派生词，当前先保留黄油与丁酸命名的基础词。' for w in cat['family'] if w not in names}
ROOT=dict(id='C0149',meaning='黄油',core='butyr- 的起点就是黄油。日常词 butter 早已进入古英语；化学家后来又借拉丁、法语命名材料形成 butyric、butyrate 这一支。',image='希腊 boutyron → 拉丁 butyrum 黄油 → 日耳曼语／古英语 → butter；拉丁命名材料 → 法语 butyrique → butyric／butyrate 化学名称。',intro='从餐桌上的黄油走到实验室的丁酸名称，中间不是“黄油变成酸”这么一条物理变化线，而是命名与借词的两条历史。',forms='butter 是经早期日耳曼语借入后继承的日常词；butyr- 保留较接近拉丁的形式，出现在化学命名中。希腊 boutyron 更早是否确为“牛＋奶酪”的组合仍有不同分析。',branches=[['食物与涂抹动作','butter'],['丁酸相关命名','butyric, butyrate']],contrasts='butyric 不等于日常的 buttery；butyrate 也不是一块黄油。共同词源说明名称关系，不抹掉各自的物质与用法区别。',practice='先说 butter the toast，再辨认 butyric acid 与 sodium butyrate：一个日常动作，两种相关但不同的化学名称。',words=names,exclude=EX)
if __name__=='__main__':
 for kind,data in [('roots',[ROOT]),('words',W)]: (OUT/(kind+'_batch200_vid_245.json')).write_text(json.dumps(data,ensure_ascii=False,indent=2))
 print('butyr: 3 new; 7 examples')
